--
-- Table structure for table `ranches`
--

DROP TABLE IF EXISTS `ranches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ranches` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(150) COLLATE utf8mb4_general_ci NOT NULL,
  `location` varchar(150) COLLATE utf8mb4_general_ci NOT NULL,
  `price_per_share` decimal(12,2) NOT NULL,
  `total_shares` int NOT NULL,
  `shares_sold` int NOT NULL DEFAULT '0',
  `acres` decimal(10,2) DEFAULT NULL,
  `amenities` text COLLATE utf8mb4_general_ci,
  `projected_roi_percent` int DEFAULT NULL COMMENT 'projected_roi_percent=annual_managment_fee	',
  `description` text COLLATE utf8mb4_general_ci,
  `status` enum('DRAFT','PUBLISHED','ARCHIVED') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PUBLISHED',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `isDeleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=not deleted,1=deleted',
  `remainingShares` decimal(10,2) DEFAULT '0.00',
  `latitude` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `longitude` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

